CREATE TABLE "s0"(c0 INTEGER NOT NULL, PRIMARY KEY(c0));
CREATE VIEW "d0"(c0) AS SELECT DISTINCT * FROM (SELECT t1.c0 AS c0 FROM (SELECT t2.c0 AS c0 FROM (SELECT c0 FROM "s0") AS t2 WHERE NOT EXISTS (SELECT 1 FROM (SELECT c0 FROM "s0") AS t3 WHERE t3.c0 = t2.c0)) AS t1 WHERE t1.c0 <> 0 AND (t1.c0 + (3)) <> 0);
